__NUXT_JSONP__("/de/how-to-apply/student-visa-f1/overseas-students", (function(a){return {data:[{details:{slug:"de",pageTitle:"aus dem Ausland | Mentor Language Institute",pageDescription:a,title:"aus dem Ausland",image:"\u002Fimages\u002Fhow-to-apply\u002Foverseas-student\u002Foverseas-student.png",subtitle:[a,"ODER","bereits ein STUDENTENVISUM haben und aus dem Ausland wieder in die USA einreisen möchten. "],category:[{title:"Bewerbungsschritte",image:"\u002Fimages\u002Fhow-to-apply\u002Foverseas-student\u002Fapplication-steps-de.png",listType:"decimal",lists:["Bewirb dich am MLI (Fülle die Online Bewerbung aus)","Reiche die Begleitdokumente für das I-20 ein","Erhalte dein I-20","Beantrage ein Studentenvisum und mache das Interview an der amerikanischen Botschaft ","Erhalte dein Studentenvisum ","Reise in die USA"],description:["Studenten sollten sich 1 oder 2 Monate vor dem gewünschten Programmbeginn am MLI bewerben. Wir führen dich durch die einzelnen Schritte nachdem du deine Online Bewerbung abgeschickt hast."],hasApplyNow:true},{title:"Stornierungsbedingungen",description:["Die Anmeldegebühr von $150 wird zum Zeitpunkt der Bewerbung fällig. Die Anmeldegebühr wird nicht zurückerstattet, unabhängig davon, ob ein Visumantrag abgelehnt oder die Einschreibung storniert wird."]},{title:"Nach dem Absenden deiner Bewerbung",image:"\u002Fimages\u002Fhow-to-apply\u002Foverseas-student\u002Fapplication-form-en.jpg",description:["Nachdem die Studenten die Online Bewerbung eingereicht haben, wird MLI die Bewerbung bearbeiten und Ihnen einen Link für iMLI (die Online-Bewerbungsseite jedes Studenten) senden. Studenten können den Bewerbungsprozess auf dem iMLI verfolgen.\u003Cbr \u002F\u003E"]}],applyOnline:{title:"Bewirb dich online",description:["Fülle die Online Bewerbung aus.\u003Cbr \u002F\u003EKontaktiere uns per e-mail für Anliegen jeglicher Art.","Bewirb dich am MLI über die Online Bewerbung weiter unten."],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Foverseas-student\u002Fapply-now-de.png",link:"\u002Fde\u002Fadmission"}},dir:"\u002Foverseas-students",path:"\u002Foverseas-students\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:30.064Z",updatedAt:"2025-05-26T12:06:27.837Z"}}],fetch:{},mutations:void 0}}("Studenten aus dem Ausland sind diejenigen, die derzeit ausserhalb der USA leben und sich für ein STUDENTENVISUM bewerben möchten.")));